
DROP TABLE IF EXISTS `musics`;
DROP TABLE IF EXISTS `albums`;
DROP TABLE IF EXISTS `artists`;
DROP TABLE IF EXISTS `countries`;
DROP TABLE IF EXISTS `genres`;


CREATE TABLE IF NOT EXISTS `albums` (
	`id`	INTEGER PRIMARY KEY AUTO_INCREMENT,
	`name`	VARCHAR(255),
	`created_date`	DATETIME DEFAULT CURRENT_TIMESTAMP,
	`modified_date`	DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS `artists` (
	`id`	INTEGER PRIMARY KEY AUTO_INCREMENT,
	`name`	VARCHAR(255),
	`created_date`	DATETIME DEFAULT CURRENT_TIMESTAMP,
	`modified_date`	DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS `countries` (
	`id`	INTEGER PRIMARY KEY AUTO_INCREMENT,
	`name`	VARCHAR(255),
	`created_date`	DATETIME DEFAULT CURRENT_TIMESTAMP,
	`modified_date`	DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS `genres` (
	`id`	INTEGER PRIMARY KEY AUTO_INCREMENT,
	`name`	VARCHAR(255),
	`created_date`	DATETIME DEFAULT CURRENT_TIMESTAMP,
	`modified_date`	DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS `musics` (
	`id`	INTEGER PRIMARY KEY AUTO_INCREMENT,
	`title`	VARCHAR(255),
	`artist`	INTEGER,
	`genre`	INTEGER,
	`album`	INTEGER,
	`country`	INTEGER,
	`cover`	TEXT,
	`counter`	INTEGER,
	`link`	TEXT,
	`created_date`	DATETIME DEFAULT CURRENT_TIMESTAMP,
	`modified_date`	DATETIME DEFAULT CURRENT_TIMESTAMP,
	FOREIGN KEY(`artist`) REFERENCES `artists`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,
	FOREIGN KEY(`genre`) REFERENCES `genres`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,
	FOREIGN KEY(`album`) REFERENCES `albums`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,
	FOREIGN KEY(`country`) REFERENCES `countries`(`id`) ON DELETE CASCADE ON UPDATE CASCADE
);






COMMIT;
